 "content": "def transform(grid):
    """Connect aligned occurrences of the foreground color with color 3."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # ARC inputs in this task have one background color and one marker color.
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    markers = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != background}
    out = [row[:] for row in grid]

    # Join consecutive markers in each row and column; the markers themselves stay unchanged.
    for r in range(h):
        cols = [c for c in range(w) if (r, c) in markers]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if (r, c) not in markers:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if (r, c) in markers]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if (r, c) not in markers:
                    out[r][c] = 3
    return out
